def solve(facts):
    def exact(s):
        return Fraction(str(s))
    def half_up(x):
        return (2*x.numerator + x.denominator) // (2*x.denominator)
    subtotal = sum(half_up(Fraction(line['qty'] * line['unit_cents']) * (1 - exact(line['discount_percent']) / 100)) for line in facts['lines'])
    tax = half_up(Fraction(subtotal) * exact(facts['tax_percent']) / 100)
    return {'subtotal_cents': subtotal, 'tax_cents': tax, 'total_cents': subtotal + tax + facts['shipping']}

def check(answer, facts):
    def decimal_ratio(s):
        s = str(s)
        parts = s.split('.')
        if len(parts) == 1:
            return (int(parts[0]), 1)
        scale = 10 ** len(parts[1])
        return (int(parts[0]) * scale + int(parts[1]), scale)
    def half_up_ratio(n, d):
        return (2*n + d) // (2*d)
    subtotal = 0
    for line in facts['lines']:
        dn, dd = decimal_ratio(line['discount_percent'])
        n = line['qty'] * line['unit_cents'] * (100*dd-dn)
        d = 100*dd
        subtotal += half_up_ratio(n, d)
    tn, td = decimal_ratio(facts['tax_percent'])
    tax = half_up_ratio(subtotal * tn, 100*td)
    return isinstance(answer, dict) and answer.get('subtotal_cents') == subtotal and answer.get('tax_cents') == tax and answer.get('total_cents') == subtotal + tax + facts['shipping']"}

